js:
var sky = root.querySelector('.mdg-frost-card-sky');
var follow = root.querySelector('.mdg-frost-card-follow');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

if (sky && !calm) {
  root.addEventListener('pointermove', function (e) {
    var r = root.getBoundingClientRect();
    if (!r.width || !r.height) return;
    root.style.setProperty('--mdg-frost-card-x', ((e.clientX - r.left) / r.width - 0.5).toFixed(3));
    root.style.setProperty('--mdg-frost-card-y', ((e.clientY - r.top) / r.height - 0.5).toFixed(3));
  });
  root.addEventListener('pointerleave', function () {
    root.style.setProperty('--mdg-frost-card-x', '0');
    root.style.setProperty('--mdg-frost-card-y', '0');
  });
}

if (follow) {
  follow.addEventListener('click', function () {
    var on = follow.getAttribute('aria-pressed') === 'true';
    follow.setAttribute('aria-pressed', on ? 'false' : 'true');
    follow.textContent = on ? 'Follow' : 'Following';
  });
}

