.mdg-glass-bar{position:relative;box-sizing:border-box;width:100%;padding:11px;border-radius:18px;overflow:hidden;isolation:isolate;background:#070911;border:1px solid #1a2131;color:#edf1fa;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
