js:
var tabs = Array.prototype.slice.call(root.querySelectorAll('.mdg-glass-bar-tab'));
var pill = root.querySelector('.mdg-glass-bar-pill');
var crumb = root.querySelector('.mdg-glass-bar-crumb');
var facts = [
  '12 services healthy · 0 alerts open',
  '486 signals in the last hour · 2 muted',
  '3 runs queued · 1 running for 4m 12s'
];
var index = 0;

function place() {
  var el = tabs[index];
  if (!pill || !el || !el.offsetWidth) return;
  pill.style.width = el.offsetWidth + 'px';
  pill.style.transform = 'translateX(' + el.offsetLeft + 'px)';
}

function select(next, focus) {
  index = (next + tabs.length) % tabs.length;
  tabs.forEach(function (t, i) {
    var on = i === index;
    t.setAttribute('aria-selected', on ? 'true' : 'false');
    t.tabIndex = on ? 0 : -1;
    if (on && focus) t.focus();
  });
  if (crumb) crumb.textContent = facts[index] || '';
  place();
}

tabs.forEach(function (t, i) {
  t.addEventListener('click', function () { select(i, false); });
  t.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight') { e.preventDefault(); select(index + 1, true); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); select(index - 1, true); }
    else if (e.key === 'Home') { e.preventDefault(); select(0, true); }
    else if (e.key === 'End') { e.preventDefault(); select(tabs.length - 1, true); }
  });
});

place();
requestAnimationFrame(function () {
  if (!root.isConnected) return;
  place();
});

if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () {
    if (!root.isConnected) { ro.disconnect(); return; }
    place();
  });
  ro.observe(root);
}

