js:
var openBtn = root.querySelector('.mdg-veil-dialog-open');
var scrim = root.querySelector('.mdg-veil-dialog-scrim');
var modal = root.querySelector('.mdg-veil-dialog-modal');
var cancel = root.querySelector('.mdg-veil-dialog-cancel');
var go = root.querySelector('.mdg-veil-dialog-go');
var cb = root.querySelector('.mdg-veil-dialog-cb');
var eyebrow = root.querySelector('.mdg-veil-dialog-eyebrow');
var heading = root.querySelector('.mdg-veil-dialog-h');
var copy = root.querySelector('.mdg-veil-dialog-p');

function focusable() {
  return Array.prototype.slice.call(modal.querySelectorAll('button, input')).filter(function (el) {
    return !el.disabled;
  });
}

function openDialog() {
  cb.checked = false;
  go.disabled = true;
  scrim.hidden = false;
  cancel.focus();
}

function closeDialog() {
  scrim.hidden = true;
  openBtn.focus();
}

function restore() {
  root.removeAttribute('data-state');
  eyebrow.textContent = 'Danger zone';
  heading.textContent = 'atlas-prod';
  copy.textContent = 'Deleting it takes every attached resource with it.';
  openBtn.textContent = 'Delete workspace';
}

openBtn.addEventListener('click', function () {
  if (root.getAttribute('data-state') === 'deleted') restore();
  else openDialog();
});

cb.addEventListener('change', function () { go.disabled = !cb.checked; });
cancel.addEventListener('click', closeDialog);

go.addEventListener('click', function () {
  root.setAttribute('data-state', 'deleted');
  eyebrow.textContent = 'Archived';
  heading.textContent = 'atlas-prod deleted';
  copy.textContent = 'Removed 2 seconds ago. A snapshot is kept for 30 days.';
  openBtn.textContent = 'Restore workspace';
  closeDialog();
});

scrim.addEventListener('mousedown', function (e) {
  if (e.target === scrim) closeDialog();
});

scrim.addEventListener('keydown', function (e) {
  if (e.key === 'Escape') { e.preventDefault(); closeDialog(); return; }
  if (e.key !== 'Tab') return;
  var list = focusable();
  if (!list.length) return;
  var first = list[0];
  var last = list[list.length - 1];
  if (e.shiftKey && root.ownerDocument.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && root.ownerDocument.activeElement === last) { e.preventDefault(); first.focus(); }
});

