var cards = Array.prototype.slice.call(root.querySelectorAll('.mdg-pane-stack-card'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.mdg-pane-stack-dots i'));
var label = root.querySelector('.mdg-pane-stack-of');
var prev = root.querySelector('.mdg-pane-stack-prev');
var next = root.querySelector('.mdg-pane-stack-next');
var front = 0;

function paint() {
  cards.forEach(function (c, i) {
    var pos = (i - front + cards.length) % cards.length;
    c.setAttribute('data-pos', String(pos));
    var face = c.querySelector('.mdg-pane-stack-face');
    if (face) {
      face.tabIndex = pos === 0 ? 0 : -1;
      face.setAttribute('aria-hidden', pos === 0 ? 'false' : 'true');
    }
  });
  dots.forEach(function (d, i) {
    d.classList.toggle('mdg-pane-stack-on', i === front);
  });
  if (label) label.textContent = 'Pass ' + (front + 1) + ' of ' + cards.length;
}

function shift(delta) {
  front = (front + delta + cards.length) % cards.length;
  paint();
}

cards.forEach(function (c, i) {
  var face = c.querySelector('.mdg-pane-stack-face');
  if (!face) return;
  face.addEventListener('click', function () {
    if (i !== front) { front = i; paint(); }
  });
});

if (prev) prev.addEventListener('click', function () { shift(-1); });
if (next) next.addEventListener('click', function () { shift(1); });

root.addEventListener('keydown', function (e) {
  if (e.key === 'ArrowRight') { e.preventDefault(); shift(1); }
  else if (e.key === 'ArrowLeft') { e.preventDefault(); shift(-1); }
});

paint();

