var toggle = root.querySelector('.mdg-side-rail-toggle');
var items = Array.prototype.slice.call(root.querySelectorAll('.mdg-side-rail-item'));
var title = root.querySelector('.mdg-side-rail-title');
var desc = root.querySelector('.mdg-side-rail-desc');
var rows = Array.prototype.slice.call(root.querySelectorAll('.mdg-side-rail-row'));

var views = {
  Inbox: ['12 unread · 2 flagged', ['Deploy digest — 09:14', 'Nadia Reyes — 08:52']],
  Drafts: ['4 drafts · 1 scheduled', ['Re: pricing tiers — 2d ago', 'Q3 retro notes — 5d ago']],
  Signals: ['3 new · latency rule', ['p95 above 400ms — 07:31', 'Error budget 82% — 06:04']],
  Archive: ['1,284 messages', ['Invoice 4471 — Aug 2', 'Offsite plan — Jul 19']]
};

if (toggle) {
  toggle.addEventListener('click', function () {
    var collapsed = root.getAttribute('data-collapsed') === 'true';
    root.setAttribute('data-collapsed', collapsed ? 'false' : 'true');
    toggle.setAttribute('aria-expanded', collapsed ? 'true' : 'false');
    toggle.setAttribute('aria-label', collapsed ? 'Collapse rail' : 'Expand rail');
  });
}

items.forEach(function (item) {
  item.addEventListener('click', function () {
    items.forEach(function (o) { o.removeAttribute('aria-current'); });
    item.setAttribute('aria-current', 'true');
    var labelEl = item.querySelector('.mdg-side-rail-label');
    var key = labelEl ? labelEl.textContent.trim() : '';
    var view = views[key];
    if (title) title.textContent = key;
    if (desc && view) desc.textContent = view[0];
    if (view) {
      rows.forEach(function (r, i) { r.textContent = view[1][i] || ''; });
    }
  });
});

