js:
var stage = root.querySelector('.mdg-toast-deck-stage');
var num = root.querySelector('.mdg-toast-deck-num');
var empty = root.querySelector('.mdg-toast-deck-empty');
var addBtn = root.querySelector('.mdg-toast-deck-add');
var clearBtn = root.querySelector('.mdg-toast-deck-clear');
var proto = stage.firstElementChild ? stage.firstElementChild.cloneNode(true) : null;
var queue = [
  ['info', 'Snapshot ready', '2.4 GB stored at 09:41.'],
  ['ok', 'Alert routed', 'Paged on-call in 1.2s.'],
  ['warn', 'Quota at 88%', 'ingest-eu throttles at 100%.'],
  ['info', 'Member joined', 'Nadia Reyes took a seat.']
];
var next = 0;

function restart(bar) {
  if (!bar) return;
  bar.style.animation = 'none';
  void bar.offsetWidth;
  bar.style.animation = '';
}

function sync() {
  var n = stage.children.length;
  if (num) num.textContent = n + (n === 1 ? ' item' : ' items');
  if (empty) empty.hidden = n > 0;
  if (clearBtn) clearBtn.disabled = n === 0;
}

function drop(toast) {
  if (toast && toast.parentNode === stage) stage.removeChild(toast);
  sync();
}

stage.addEventListener('animationend', function (e) {
  if (e.animationName === 'mdg-toast-deck-life') drop(e.target.parentNode);
});

stage.addEventListener('click', function (e) {
  var t = e.target;
  var toast = t.closest ? t.closest('.mdg-toast-deck-toast') : null;
  if (!toast) return;
  if (t.classList.contains('mdg-toast-deck-x')) { drop(toast); return; }
  if (t.classList.contains('mdg-toast-deck-undo')) {
    toast.setAttribute('data-kind', 'ok');
    toast.querySelector('.mdg-toast-deck-title').textContent = 'Change undone';
    toast.querySelector('.mdg-toast-deck-desc').textContent = 'Restored the previous state.';
    t.remove();
    restart(toast.querySelector('.mdg-toast-deck-life'));
  }
});

if (addBtn && proto) {
  addBtn.addEventListener('click', function () {
    var spec = queue[next % queue.length];
    next++;
    var node = proto.cloneNode(true);
    node.setAttribute('data-kind', spec[0]);
    node.setAttribute('data-live', 'true');
    node.querySelector('.mdg-toast-deck-title').textContent = spec[1];
    node.querySelector('.mdg-toast-deck-desc').textContent = spec[2];
    stage.appendChild(node);
    while (stage.children.length > 3) stage.removeChild(stage.firstElementChild);
    sync();
  });
}

if (clearBtn) {
  clearBtn.addEventListener('click', function () {
    while (stage.firstElementChild) stage.removeChild(stage.firstElementChild);
    sync();
  });
}

sync();

