js:
var seek = root.querySelector('.mdg-sound-pane-seek');
var cur = root.querySelector('.mdg-sound-pane-cur');
var play = root.querySelector('.mdg-sound-pane-play');
var shuffle = root.querySelector('.mdg-sound-pane-shuffle');
var prev = root.querySelector('.mdg-sound-pane-prev');
var nextBtn = root.querySelector('.mdg-sound-pane-next');
var titleEl = root.querySelector('.mdg-sound-pane-title');
var artistEl = root.querySelector('.mdg-sound-pane-artist');
var durEl = root.querySelector('.mdg-sound-pane-dur');

var tracks = [
  ['Neon Kelp', 'Hollow Coast · Tidal Drift', 214],
  ['Slow Aperture', 'Mira Vance · Long Exposure', 187],
  ['Cold Harbour', 'Ptarmigan · Northlight', 251]
];
var at = 0;
var pos = 63;

function clock(s) {
  var m = Math.floor(s / 60);
  var r = Math.floor(s % 60);
  return m + ':' + (r < 10 ? '0' : '') + r;
}

function paint() {
  var dur = tracks[at][2];
  if (seek) {
    seek.max = String(dur);
    seek.value = String(pos);
  }
  root.style.setProperty('--mdg-sound-pane-p', (pos / dur * 100).toFixed(2) + '%');
  if (cur) cur.textContent = clock(pos);
  if (durEl) durEl.textContent = clock(dur);
}

function load(i) {
  at = (i + tracks.length) % tracks.length;
  pos = 0;
  if (titleEl) titleEl.textContent = tracks[at][0];
  if (artistEl) artistEl.textContent = tracks[at][1];
  paint();
}

if (play) {
  play.addEventListener('click', function () {
    var on = root.getAttribute('data-playing') === 'true';
    root.setAttribute('data-playing', on ? 'false' : 'true');
    play.setAttribute('aria-pressed', on ? 'false' : 'true');
    play.setAttribute('aria-label', on ? 'Play' : 'Pause');
  });
}

if (shuffle) {
  shuffle.addEventListener('click', function () {
    var on = shuffle.getAttribute('aria-pressed') === 'true';
    shuffle.setAttribute('aria-pressed', on ? 'false' : 'true');
  });
}

if (prev) prev.addEventListener('click', function () { load(at - 1); });
if (nextBtn) nextBtn.addEventListener('click', function () { load(at + 1); });

if (seek) {
  seek.addEventListener('input', function () {
    pos = Number(seek.value) || 0;
    paint();
  });
}

var tick = setInterval(function () {
  if (!root.isConnected) { clearInterval(tick); return; }
  if (root.getAttribute('data-playing') !== 'true') return;
  pos += 1;
  if (pos >= tracks[at][2]) { load(at + 1); return; }
  paint();
}, 1000);

paint();

