js:
var valueEl = root.querySelector('.mdg-stat-tile-value');
var deltaNum = root.querySelector('.mdg-stat-tile-delta b');
var caret = root.querySelector('.mdg-stat-tile-caret');
var area = root.querySelector('.mdg-stat-tile-area');
var line = root.querySelector('.mdg-stat-tile-line');
var buttons = Array.prototype.slice.call(root.querySelectorAll('.mdg-stat-tile-r'));
var foot = root.querySelector('.mdg-stat-tile-foot');

var data = {
  '7d': { value: 4.82, delta: 0.41, foot: 'vs prior 7 days', series: [3.86, 4.12, 3.79, 4.35, 4.18, 4.61, 4.82] },
  '30d': { value: 4.41, delta: 0.18, foot: 'vs prior 30 days', series: [3.62, 3.9, 4.05, 3.84, 4.2, 4.31, 4.12, 4.4, 4.28, 4.41] },
  '90d': { value: 3.96, delta: -0.24, foot: 'vs prior 90 days', series: [4.6, 4.42, 4.51, 4.2, 4.31, 4.08, 4.15, 3.88, 4.02, 3.96] }
};
var shown = 4.82;
var raf = 0;

function build(vals, close) {
  var w = 120, h = 32;
  var min = Math.min.apply(null, vals);
  var max = Math.max.apply(null, vals);
  var span = (max - min) || 1;
  var d = '';
  for (var i = 0; i < vals.length; i++) {
    var x = (i / (vals.length - 1)) * w;
    var y = 2 + (1 - (vals[i] - min) / span) * h;
    d += (i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1);
  }
  if (close) d += 'L120 36L0 36Z';
  return d;
}

function ramp(to) {
  var from = shown;
  var start = 0;
  if (raf) cancelAnimationFrame(raf);
  if (root.ownerDocument.hidden) {
    shown = to;
    if (valueEl) valueEl.innerHTML = to.toFixed(2) + '<small>%</small>';
    return;
  }
  function step(t) {
    if (!root.isConnected) return;
    if (!start) start = t;
    var k = Math.min(1, (t - start) / 460);
    var e = 1 - Math.pow(1 - k, 3);
    shown = from + (to - from) * e;
    if (valueEl) valueEl.innerHTML = shown.toFixed(2) + '<small>%</small>';
    if (k < 1) raf = requestAnimationFrame(step);
    else { shown = to; raf = 0; }
  }
  raf = requestAnimationFrame(step);
}

function apply(key) {
  var set = data[key];
  if (!set) return;
  root.setAttribute('data-trend', set.delta < 0 ? 'down' : 'up');
  if (deltaNum) deltaNum.textContent = Math.abs(set.delta).toFixed(2);
  if (caret) caret.textContent = set.delta < 0 ? '▼' : '▲';
  if (foot) foot.textContent = set.foot;
  if (line) line.setAttribute('d', build(set.series, false));
  if (area) area.setAttribute('d', build(set.series, true));
  ramp(set.value);
}

buttons.forEach(function (b) {
  b.addEventListener('click', function () {
    buttons.forEach(function (o) { o.setAttribute('aria-pressed', 'false'); });
    b.setAttribute('aria-pressed', 'true');
    apply(b.textContent.trim());
  });
});

apply('7d');
